if (c == "'" || c == "\"") {
    # A quote beginning with no whitespace before it (cur already
    # has characters in it) CONTINUES the current word rather than
    # starting a new token -- ordinary shell word semantics
    # (a"b"c is one word, "ab"'cd' is one word). This is what
    # keeps --git-dir="<path>" or -c core.pager="cat" as a single
    # token identical to the unquoted form: without it, the
    # tokenizer split the token in two at the opening quote
    # (--git-dir= as its own word, the path as a separate word),
    # which made --git-dir= look like a standalone boolean flag to
    # skip_global_opts and left the actual path as the next
    # token -- never recognized as "push", so the whole invocation
    # went unclassified. Accumulating into `cur` instead of
    # emitting the quoted interior as its own TOK entry is the fix;
    # no `=`-specific special case is needed.
    start = i + 1
    if (c == "\"") {
        j = start
        while (j <= n) {
            if (substr(text, j, 1) == "\\" && j < n) { j += 2; continue }
            if (substr(text, j, 1) == c) break
            j++
        }
    } else {
        j = start
        while (j <= n && substr(text, j, 1) != c) j++
    }
    if (j > n) {
        # Unterminated quote -- not a closed token; pass the quote
        # character through literally and keep scanning.
        cur = cur c
        i++
        continue
    }
    interior = substr(text, start, j - start)
    cur = cur interior
    i = j + 1
    continue
}

