# The ONE routine that knows global-option shape. Given tok[] and a
# starting index, skips any run of global option tokens -- anything
# starting with "-", plus the following bare value for the
# space-separated value-taking forms -- and returns the index of the
# first non-option token (the subcommand), or 0 if none before n. Fills
# CVALS[1..NCVALS] with each -C value seen, left-to-right (git's own
# semantics: each -C is relative to the previous). Fills GITDIR with the
# LAST --git-dir value seen (git's own semantics: --git-dir directly
# names the repository and is authoritative over any -C on the same
# invocation, in either order -- verified against real git, not assumed),
# or "" if none was given.
function skip_global_opts(tok, start, n,    i) {
    NCVALS = 0
    GITDIR = ""
    i = start
    while (i <= n) {
        if (substr(tok[i], 1, 1) != "-") {
            return i
        }
        if (is_global_valued(tok[i])) {
            if (tok[i] == "-C" && i < n) {
                NCVALS++
                CVALS[NCVALS] = strip_one_quote(tok[i + 1])
            } else if (tok[i] == "--git-dir" && i < n) {
                GITDIR = strip_one_quote(tok[i + 1])
            }
            i += 2
        } else {
            i += 1
        }
    }
    return 0
}

